/* repo.ts's appendChangeLog generates its own id via newId('log'), which produces a
   string like 'log-2mks435g'. The changelog table's id column is defined in the
   database schema as `uuid primary key default gen_random_uuid()` - a genuine UUID
   column with a server-side default generator. Inserting an explicitly-generated
   non-UUID string into a uuid column is rejected by Postgres with a type error.

   This test file proves the fix: appendChangeLog no longer generates or sends its
   own id - let Postgres's gen_random_uuid() supply it. */

vi.mock('../supabase.js', async () => {
  const actual = await vi.importActual('../supabase.js');
  return {
    ...actual,
    supabaseAdmin: {
      from: vi.fn().mockReturnValue({
        insert: vi.fn().mockResolvedValue({ data: undefined, error: undefined }),
        maybeSingle: vi.fn().mockResolvedValue(undefined),
      }),
      auth: {
        admin: {
          listUsers: vi.fn().mockResolvedValue({ users: [] }),
          getUserById: vi.fn().mockResolvedValue({ user: {} }),
          generateLink: vi.fn().mockResolvedValue({ properties: { action_link: 'http://test.com' } }),
