vi.mock('../repo.js', () => ({
  listChangeLog: vi.fn(),
  getChangeLogEntry: vi.fn(),
}));

import * as repo from '../repo.js';
import { supabaseAdmin } from '../supabase.js';

const VALID_ENTRY = {
  Who: 'test-user',
  Action: 'create',
  Collection: 'virtues',
  ObjectId: 'v-123',
  ObjectName: 'Test Virtue',
  Before: null,
  After: { Name: 'Test Virtue' },
};

describe('appendChangeLog id generation fix', () => {
  beforeEach(() => {
    vi.resetAllMocks();
    vi.mocked(repo.listChangeLog).mockResolvedValue([]);
    vi.mocked(repo.getChangeLogEntry).mockResolvedValue(null);
  });

  it('inserts the payload to the mocked client, and the payload does not include an id key at all', async () => {
    // Arrange: mock the supabaseAdmin.from('changelog').insert() call
    const insertMock = vi.fn();
    vi.spyOn(supabaseAdmin.from('changelog'), 'insert').mockReturnValue({
      select: vi.fn().mockReturnValue({
        then: vi.fn().mockResolvedValue({ data: undefined, error: undefined }),
      }),
    } as any);
    vi.mocked(supabaseAdmin.from('changelog').insert).mockReturnValue({
      select: vi.fn().mockResolvedValue({ data: undefined, error: undefined }),
    } as any);

    // Act
    await repo.appendChangeLog(VALID_ENTRY);

    // Assert: the insert was called exactly once, with a payload that does not include 'id'
    expect(supabaseAdmin.from('changelog').insert).toHaveBeenCalledTimes(1);
    const insertCall = supabaseAdmin.from('changelog').insert.mock.calls[0][0];
    expect(insertCall).not.toHaveProperty('id');

    // Assert: the payload includes exactly the columns the changelog table declares
    expect(insertCall).toEqual(expect.objectContaining({
      at: expect.any(String),
      who: 'test-user',
      action: 'create',
      collection: 'virtues',
      object_id: 'v-123',
      object_name: 'Test Virtue',
      before: null,
      after: { Name: 'Test Virtue' },
    }));
  });

  it('the payload includes exactly the columns the changelog table declares, correctly mapped to snake_case', async () => {
    const insertMock = vi.fn();
    vi.mocked(supabaseAdmin.from('changelog').insert).mockReturnValue({
      select: vi.fn().mockResolvedValue({ data: undefined, error: undefined }),
    } as any);

    const PascalCaseEntry = {
      Who: 'Test User',
      Action: 'update' as const,
      Collection: 'items',
      ObjectId: 'item-456',
      ObjectName: 'Test Item',
      Before: { Name: 'Old Name' },
      After: { Name: 'New Name' },
    };

    await repo.appendChangeLog(PascalCaseEntry);

    const insertCall = supabaseAdmin.from('changelog').insert.mock.calls[0][0];

    expect(insertCall.at).toBeDefined();
    expect(insertCall.who).toBe('Test User');
    expect(insertCall.action).toBe('update');
    expect(insertCall.collection).toBe('items');
    expect(insertCall.object_id).toBe('item-456');
    expect(insertCall.object_name).toBe('Test Item');
  });

  it('if the mocked insert call itself rejects, the error still propagates (is not silently swallowed)', async () => {
    const mockError = new Error('Database error');
    vi.mocked(supabaseAdmin.from('changelog').insert).mockRejectedValue(mockError);

    await expect(repo.appendChangeLog(VALID_ENTRY)).rejects.toThrow(mockError);
  });
});

