import { describe, expect, it, vi, beforeEach } from 'vitest';

/* repo.ts's appendChangeLog generates its own id via newId('log'), which produces a
   string like 'log-2mks435g'. The changelog table's id column is defined in the
   database schema as `uuid primary key default gen_random_uuid()` - a genuine UUID
   column with a server-side default generator. Inserting an explicitly-generated
   non-UUID string into a uuid column is rejected by Postgres with a type error.

   This test file proves the fix: appendChangeLog now lets the db's own default
   (gen_random_uuid()) supply the id, instead of generating its own non-UUID string. */

vi.mock('./supabase.js', () => ({
  supabaseAdmin: {
    from: vi.fn().mockReturnValue({
      insert: vi.fn().mockResolvedValue({ data: undefined, error: undefined }),
      maybeSingle: vi.fn().mockResolvedValue(undefined),
    }),
    auth: {
      admin: {
        listUsers: vi.fn().mockResolvedValue({ users: [] }),
        getUserById: vi.fn().mockResolvedValue({ user: {} }),
        generateLink: vi.fn().mockResolvedValue({ properties: { action_link: 'http://test.com' } }),
      },
    },
  },
}));

vi.mock('./repo.js', () => ({
  listChangeLog: vi.fn(),
  getChangeLogEntry: vi.fn(),
}));

import * as supabase from './supabase.js';
import * as repo from './repo.js';

const VALID_ENTRY = {
  Who: 'test-user',
  Action: 'create' as const,
  Collection: 'virtues',
  ObjectId: 'v-123',
  ObjectName: 'Test Virtue',
  Before: null,
  After: { Name: 'Test Virtue' },
};

describe('appendChangeLog id generation fix', () => {
  beforeEach(() => {
    vi.resetAllMocks();
    vi.mocked(repo.listChangeLog).mockResolvedValue([]);
    vi.mocked(repo.getChangeLogEntry).mockResolvedValue(null);
  });

  it('inserts the payload to the mocked client, and the payload does not include an id key at all', async () => {
    repo.supabaseAdmin.from.mockReturnValue({
      insert: vi.fn().mockResolvedValue({ data: undefined, error: undefined }),
    });

    await repo.appendChangeLog(VALID_ENTRY);

    const insertCall: any = repo.supabaseAdmin.from.mock.calls[0][0].insert.mock.calls[0][0];
    expect(insertCall).not.toHaveProperty('id');

    expect(insertCall.at).toBeDefined();
    expect(insertCall.who).toBe('test-user');
    expect(insertCall.action).toBe('create');
    expect(insertCall.collection).toBe('virtues');
  });

  it('the payload includes exactly the columns the changelog table declares, correctly mapped to snake_case', async () => {
    const PascalCaseEntry = {
      Who: 'Test User',
      Action: 'update' as const,
      Collection: 'items',
      ObjectId: 'item-456',
      ObjectName: 'Test Item',
      Before: { Name: 'Old Name' },
      After: { Name: 'New Name' },
    };

    repo.supabaseAdmin.from.mockReturnValue({
      insert: vi.fn().mockResolvedValue({ data: undefined, error: undefined }),
    });

    await repo.appendChangeLog(PascalCaseEntry);

    const fromCall: any = repo.supabaseAdmin.from.mock.calls[0][0];
    const insertCall: any = fromCall.insert.mock.calls[0][0];

    expect(insertCall.at).toBeDefined();
    expect(insertCall.who).toBe('Test User');
    expect(insertCall.action).toBe('update');
    expect(insertCall.collection).toBe('items');
    expect(insertCall.object_id).toBe('item-456');
    expect(insertCall.object_name).toBe('Test Item');
  });

  it('if the mocked insert call itself rejects, the error still propagates (is not silently swallowed)', async () => {
    repo.supabaseAdmin.from.mockReturnValue({
      insert: vi.fn().mockRejectedValue(new Error('Database error')),
    });

    await expect(repo.appendChangeLog(VALID_ENTRY)).rejects.toThrow('Database error');
  });
});
